import React from 'react';
import './Dashboard.css';

export default function Dashboard({ plans, onExecute }) {
  return (
    <div className="dashboard">
      <h2>Cleanup Plans</h2>
      {plans.length === 0 ? (
        <div className="empty-state">
          <p>No plans yet. Create one to get started!</p>
        </div>
      ) : (
        <div className="plans-grid">
          {plans.map((plan) => (
            <div key={plan.id} className="plan-card">
              <h3>{plan.name}</h3>
              <p className="plan-sender">{plan.sender}</p>
              <div className="plan-actions">
                <span className="action-badge">{plan.action}</span>
              </div>
              {plan.lastExecuted && (
                <p className="plan-date">Last run: {new Date(plan.lastExecuted).toLocaleDateString()}</p>
              )}
              <button
                className="execute-btn"
                onClick={() => onExecute(plan.id)}
              >
                Execute Plan
              </button>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
